def tbl(head, rows):
    out = "| " + " | ".join(head) + " |\n|" + "---|" * len(head) + "\n"
    for r in rows:
        out += "| " + " | ".join(str(x) for x in r) + " |\n"
    return out + "\n"


def f2(x):
    return str(round(x, 2)).replace(".", ",")


